CREATE TABLE IF NOT EXISTS shop_settings(id BIGINT PRIMARY KEY CHECK(id=1),currency TEXT NOT NULL,tax_bps BIGINT NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000),shipping_minor BIGINT NOT NULL DEFAULT 0 CHECK(shipping_minor>=0),tax_shipping BIGINT NOT NULL DEFAULT 0 CHECK(tax_shipping IN (0,1)),version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS shop_products(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('physical','digital','membership','booking')),entitlement TEXT NOT NULL DEFAULT '',access_seconds BIGINT NOT NULL DEFAULT 0 CHECK(access_seconds>=0),download_id TEXT NOT NULL DEFAULT '',published BIGINT NOT NULL DEFAULT 0 CHECK(published IN (0,1)),version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS shop_catalog ON shop_products(published,created_at DESC,id);
CREATE TABLE IF NOT EXISTS shop_variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES shop_products(id),title TEXT NOT NULL,sku TEXT NOT NULL UNIQUE,price_minor BIGINT NOT NULL CHECK(price_minor>=0),member_price_minor BIGINT NOT NULL DEFAULT -1 CHECK(member_price_minor>=-1),member_key TEXT NOT NULL DEFAULT '',stock_total BIGINT NOT NULL CHECK(stock_total>=-1),held BIGINT NOT NULL DEFAULT 0 CHECK(held>=0),sold BIGINT NOT NULL DEFAULT 0 CHECK(sold>=0),billing_interval TEXT NOT NULL DEFAULT '' CHECK(billing_interval IN ('','day','week','month','year')),active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)),version BIGINT NOT NULL DEFAULT 1,CHECK(stock_total=-1 OR held+sold<=stock_total));
CREATE INDEX IF NOT EXISTS shop_variant_product ON shop_variants(product_id,active,id);
CREATE TABLE IF NOT EXISTS shop_discounts(code TEXT PRIMARY KEY,title TEXT NOT NULL,bps BIGINT NOT NULL CHECK(bps BETWEEN 1 AND 10000),starts_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,max_uses BIGINT NOT NULL CHECK(max_uses>=0),held BIGINT NOT NULL DEFAULT 0 CHECK(held>=0),used BIGINT NOT NULL DEFAULT 0 CHECK(used>=0),member_key TEXT NOT NULL DEFAULT '',product_id TEXT NOT NULL DEFAULT '',reward_id TEXT NOT NULL DEFAULT '',active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)),version BIGINT NOT NULL DEFAULT 1,CHECK(max_uses=0 OR held+used<=max_uses));
CREATE TABLE IF NOT EXISTS shop_carts(user_id TEXT PRIMARY KEY REFERENCES users(id),version BIGINT NOT NULL DEFAULT 1,updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS shop_cart_lines(user_id TEXT NOT NULL REFERENCES shop_carts(user_id),variant_id TEXT NOT NULL REFERENCES shop_variants(id),slot_id TEXT NOT NULL DEFAULT '',quantity BIGINT NOT NULL CHECK(quantity BETWEEN 1 AND 100),PRIMARY KEY(user_id,variant_id,slot_id));
CREATE TABLE IF NOT EXISTS shop_resources(id TEXT PRIMARY KEY,title TEXT NOT NULL,staff_id TEXT NOT NULL DEFAULT '',active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)),version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS shop_slots(id TEXT PRIMARY KEY,resource_id TEXT NOT NULL REFERENCES shop_resources(id),variant_id TEXT NOT NULL REFERENCES shop_variants(id),starts_at BIGINT NOT NULL,ends_at BIGINT NOT NULL,capacity BIGINT NOT NULL CHECK(capacity BETWEEN 1 AND 1000),held BIGINT NOT NULL DEFAULT 0 CHECK(held>=0),booked BIGINT NOT NULL DEFAULT 0 CHECK(booked>=0),active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)),version BIGINT NOT NULL DEFAULT 1,CHECK(ends_at>starts_at),CHECK(held+booked<=capacity));
CREATE INDEX IF NOT EXISTS shop_resource_calendar ON shop_slots(resource_id,active,starts_at,ends_at);
CREATE INDEX IF NOT EXISTS shop_booking_catalog ON shop_slots(variant_id,active,starts_at,id);
CREATE TABLE IF NOT EXISTS shop_subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),variant_id TEXT NOT NULL REFERENCES shop_variants(id),entitlement TEXT NOT NULL,price_minor BIGINT NOT NULL CHECK(price_minor>=0),billing_interval TEXT NOT NULL CHECK(billing_interval IN ('day','week','month','year')),period_start BIGINT NOT NULL,period_end BIGINT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','active','past_due','cancel_at_end','cancelled')),provider TEXT NOT NULL CHECK(provider IN ('offline','stripe')),provider_ref TEXT NOT NULL DEFAULT '',provider_cancel_pending BIGINT NOT NULL DEFAULT 0 CHECK(provider_cancel_pending IN (0,1)),provider_cancel_at BIGINT NOT NULL DEFAULT 0 CHECK(provider_cancel_at>=0),grant_id TEXT NOT NULL DEFAULT '',next_variant TEXT NOT NULL DEFAULT '',next_price_minor BIGINT NOT NULL DEFAULT -1 CHECK(next_price_minor>=-1),version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,CHECK(period_end>period_start));
CREATE UNIQUE INDEX IF NOT EXISTS shop_subscription_provider ON shop_subscriptions(provider_ref) WHERE provider_ref<>'';
CREATE INDEX IF NOT EXISTS shop_subscription_due ON shop_subscriptions(state,period_end,id);
CREATE INDEX IF NOT EXISTS shop_subscription_customer ON shop_subscriptions(user_id,created_at DESC,id);
CREATE TABLE IF NOT EXISTS shop_orders(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL,request_digest TEXT NOT NULL,cart_version BIGINT NOT NULL,customer_name TEXT NOT NULL,customer_email TEXT NOT NULL,shipping_address TEXT NOT NULL,currency TEXT NOT NULL,subtotal_minor BIGINT NOT NULL CHECK(subtotal_minor>=0),discount_minor BIGINT NOT NULL CHECK(discount_minor>=0),discount_bps BIGINT NOT NULL DEFAULT 0 CHECK(discount_bps BETWEEN 0 AND 10000),discount_base_minor BIGINT NOT NULL DEFAULT 0 CHECK(discount_base_minor>=0),tax_minor BIGINT NOT NULL CHECK(tax_minor>=0),shipping_minor BIGINT NOT NULL CHECK(shipping_minor>=0),total_minor BIGINT NOT NULL CHECK(total_minor>=0),tax_bps BIGINT NOT NULL CHECK(tax_bps BETWEEN 0 AND 10000),tax_shipping BIGINT NOT NULL CHECK(tax_shipping IN (0,1)),discount_code TEXT NOT NULL DEFAULT '',reward_claim TEXT NOT NULL DEFAULT '',referral_id TEXT NOT NULL DEFAULT '',commission_bps BIGINT NOT NULL DEFAULT 0 CHECK(commission_bps BETWEEN 0 AND 10000),provider TEXT NOT NULL CHECK(provider IN ('offline','stripe')),provider_ref TEXT NOT NULL DEFAULT '',payment_ref TEXT NOT NULL DEFAULT '',payment_state TEXT NOT NULL CHECK(payment_state IN ('awaiting','paid','partially_refunded','refunded','cancelled','failed','needs_refund')),fulfillment TEXT NOT NULL DEFAULT 'unfulfilled' CHECK(fulfillment IN ('unfulfilled','fulfilled','cancel_requested','cancelled')),paid_minor BIGINT NOT NULL DEFAULT 0 CHECK(paid_minor>=0),refunded_minor BIGINT NOT NULL DEFAULT 0 CHECK(refunded_minor>=0 AND refunded_minor<=paid_minor),expires_at BIGINT NOT NULL,subscription_id TEXT NOT NULL DEFAULT '',period_start BIGINT NOT NULL DEFAULT 0,period_end BIGINT NOT NULL DEFAULT 0,target_price_minor BIGINT NOT NULL DEFAULT 0 CHECK(target_price_minor>=0),purpose TEXT NOT NULL DEFAULT 'purchase' CHECK(purpose IN ('purchase','renewal','upgrade')),version BIGINT NOT NULL DEFAULT 1,created_at BIGINT NOT NULL,UNIQUE(user_id,request_key),CHECK(total_minor=subtotal_minor-discount_minor+tax_minor+shipping_minor));
CREATE INDEX IF NOT EXISTS shop_order_customer ON shop_orders(user_id,created_at DESC,id);
CREATE INDEX IF NOT EXISTS shop_order_pending ON shop_orders(payment_state,expires_at,id);
CREATE INDEX IF NOT EXISTS shop_order_work ON shop_orders(fulfillment,payment_state,created_at,id);
CREATE UNIQUE INDEX IF NOT EXISTS shop_order_provider ON shop_orders(provider_ref) WHERE provider_ref<>'';
CREATE UNIQUE INDEX IF NOT EXISTS shop_order_period ON shop_orders(subscription_id,period_start,purpose) WHERE subscription_id<>'' AND purpose='renewal';
CREATE TABLE IF NOT EXISTS shop_order_lines(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES shop_orders(id),variant_id TEXT NOT NULL REFERENCES shop_variants(id),product_id TEXT NOT NULL REFERENCES shop_products(id),title TEXT NOT NULL,sku TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('physical','digital','membership','booking')),quantity BIGINT NOT NULL CHECK(quantity BETWEEN 1 AND 100),unit_minor BIGINT NOT NULL CHECK(unit_minor>=0),line_minor BIGINT NOT NULL CHECK(line_minor>=0),slot_id TEXT NOT NULL DEFAULT '',entitlement TEXT NOT NULL DEFAULT '',access_seconds BIGINT NOT NULL DEFAULT 0,allocation TEXT NOT NULL CHECK(allocation IN ('held','sold','released','restocked')),grant_id TEXT NOT NULL DEFAULT '',billing_interval TEXT NOT NULL DEFAULT '',CHECK(line_minor=unit_minor*quantity));
CREATE INDEX IF NOT EXISTS shop_line_order ON shop_order_lines(order_id,id);
CREATE INDEX IF NOT EXISTS shop_line_stock ON shop_order_lines(variant_id,allocation);
CREATE INDEX IF NOT EXISTS shop_line_slot ON shop_order_lines(slot_id,allocation);
CREATE TABLE IF NOT EXISTS shop_payments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES shop_orders(id),provider TEXT NOT NULL,reference TEXT NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>=0),currency TEXT NOT NULL,created_at BIGINT NOT NULL,UNIQUE(provider,reference),UNIQUE(order_id));
CREATE TABLE IF NOT EXISTS shop_refunds(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES shop_orders(id),request_key TEXT NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),reason TEXT NOT NULL,restock BIGINT NOT NULL CHECK(restock IN (0,1)),state TEXT NOT NULL CHECK(state IN ('pending','confirmed','failed')),provider_ref TEXT NOT NULL DEFAULT '',created_at BIGINT NOT NULL,UNIQUE(order_id,request_key));
CREATE INDEX IF NOT EXISTS shop_refund_order ON shop_refunds(order_id,state,id);
CREATE TABLE IF NOT EXISTS shop_notifications(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES shop_orders(id),kind TEXT NOT NULL CHECK(kind IN ('confirmation','reminder','cancellation','billing')),slot_id TEXT NOT NULL DEFAULT '',due_at BIGINT NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','queued','cancelled')),message_id TEXT NOT NULL DEFAULT '',created_at BIGINT NOT NULL,UNIQUE(order_id,kind,slot_id));
CREATE INDEX IF NOT EXISTS shop_notification_due ON shop_notifications(state,due_at,id);
CREATE TABLE IF NOT EXISTS shop_provider_events(id TEXT PRIMARY KEY,digest TEXT NOT NULL,body TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','processed','ignored')),attempts BIGINT NOT NULL DEFAULT 0 CHECK(attempts>=0),next_at BIGINT NOT NULL DEFAULT 0 CHECK(next_at>=0),created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS shop_event_work ON shop_provider_events(state,next_at,created_at,id);
CREATE TABLE IF NOT EXISTS shop_reward_redemptions(claim_id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES shop_orders(id),state TEXT NOT NULL CHECK(state IN ('held','used','released')));

CREATE UNIQUE INDEX IF NOT EXISTS promotion_claim_code ON promotion_claims(code);
CREATE TABLE IF NOT EXISTS shop_payouts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS shop_payout_user ON shop_payouts(user_id,currency,created_at,id);
CREATE TABLE IF NOT EXISTS shop_history(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES shop_orders(id),actor TEXT NOT NULL,action TEXT NOT NULL,amount_minor BIGINT NOT NULL DEFAULT 0 CHECK(amount_minor>=0),created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS shop_history_order ON shop_history(order_id,created_at,id);
CREATE INDEX IF NOT EXISTS shop_catalog_cursor ON shop_products(published,id);
CREATE INDEX IF NOT EXISTS shop_order_customer_cursor ON shop_orders(user_id,id);
CREATE INDEX IF NOT EXISTS shop_subscription_customer_cursor ON shop_subscriptions(user_id,id);
CREATE INDEX IF NOT EXISTS shop_resource_staff ON shop_resources(staff_id,id);
CREATE INDEX IF NOT EXISTS shop_subscription_provider_due ON shop_subscriptions(provider,state,period_end,id);

CREATE INDEX IF NOT EXISTS shop_provider_cancel_due ON shop_subscriptions(provider_cancel_pending,provider_cancel_at,id);
